pat = re.compile(r'^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$')

def derive(u, s):
    if s is None or (isinstance(s, float) and pd.isna(s)):
        return None, None
    s = str(s).strip().split('T')[0].strip()
    if not s:
        return None, None
    m = pat.match(s)
    if not m:
        return None, None
    y, mo, d = m.group(1), m.group(2), m.group(3)
    y = int(y)
    try:
        if d is not None:
            return date(y, int(mo), int(d)), None
        if mo is not None:
            dt = date(y, int(mo), 1)
            flag = 'D'
        else:
            dt = date(y, 1, 1)
            flag = 'M'
    except ValueError:
        return None, None
    t = trt.get(u)
    if t is not None and dt < t:
        if flag == 'D' and t.year == dt.year and t.month == dt.month:
            dt = t
        elif flag == 'M' and t.year == dt.year:
            dt = t
    return dt, flag

res = [derive(u, s) for u, s in zip(ae['USUBJID'], ae['AESTDTC'])]
