import os
import re
import datetime as dt

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

IN_DIR = "/work/inputs"
OUT_DIR = "/work/out"
os.makedirs(OUT_DIR, exist_ok=True)


def to_date(v):
    """Convert an ISO 8601 value (or date object) to a calendar date, or None."""
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(v, pd.Timestamp):
        return dt.date(v.year, v.month, v.day)
    if isinstance(v, dt.date):
        return dt.date(v.year, v.month, v.day)
    s = str(v).strip()
    if s == "":
        return None
    s = s.split("T")[0].strip()
    m = re.fullmatch(r"(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?", s)
    if m is None:
        return None
    y = int(m.group(1))
    mo = int(m.group(2)) if m.group(2) else 1
    d = int(m.group(3)) if m.group(3) else 1
    try:
        return dt.date(y, mo, d)
    except ValueError:
        return None


dm = pd.read_parquet(os.path.join(IN_DIR, "dm.parquet"))
ae = pd.read_parquet(os.path.join(IN_DIR, "ae.parquet"))
lb = pd.read_parquet(os.path.join(IN_DIR, "lb.parquet"))
adsl_up = pd.read_parquet(os.path.join(IN_DIR, "adsl_upstream.parquet"))

# Collect the latest usable date per subject
latest = {}


def add(usubjid, d):
    if d is None or usubjid is None or (isinstance(usubjid, float) and pd.isna(usubjid)):
        return
    cur = latest.get(usubjid)
    if cur is None or d > cur:
        latest[usubjid] = d
    else:
        latest.setdefault(usubjid, cur)


for uid, st, en in zip(ae["USUBJID"], ae["AESTDTC"], ae["AEENDTC"]):
    add(uid, to_date(st))
    add(uid, to_date(en))

for uid, dtc in zip(lb["USUBJID"], lb["LBDTC"]):
    add(uid, to_date(dtc))

for uid, trte in zip(adsl_up["USUBJID"], adsl_up["TRTEDT"]):
    add(uid, to_date(trte))

# One row per DM subject
subjects = dm["USUBJID"].dropna().astype(str).drop_duplicates().tolist()
usubjids = []
vals = []
for s in subjects:
    usubjids.append(s)
    vals.append(latest.get(s))

table = pa.table({
    "USUBJID": pa.array(usubjids, type=pa.string()),
    "LSTALVDT": pa.array(vals, type=pa.date32()),
})

pq.write_table(table, os.path.join(OUT_DIR, "result.parquet"))
